mapper.select:
SELECT u.user_id AS userId, u.name AS name, u.username AS username, u.major AS major, COALESCE(d.dept_name, '') AS deptName, COALESCE(rc.cycle_name,'') AS cycleName, agg.maxTime AS latestInterviewTime, COALESCE(se.location, sl.location) AS interviewLocation FROM ( SELECT s.resume_id AS resumeId, r.user_id AS userId, MAX(s.interview_time) AS maxTime FROM interview_schedule s INNER JOIN resume r ON r.resume_id = s.resume_id
AND s.cycle_id = #{cycleId}
GROUP BY s.resume_id, r.user_id ) agg INNER JOIN user u ON u.user_id = agg.userId AND u.is_deleted = 0 LEFT JOIN department d ON d.dept_id = u.dept_id LEFT JOIN ( SELECT r.user_id AS userId, MAX(rc.cycle_name) AS cycle_name FROM interview_schedule s INNER JOIN resume r ON r.resume_id = s.resume_id LEFT JOIN recruitment_cycle rc ON rc.cycle_id = s.cycle_id
AND s.cycle_id = #{cycleId}
GROUP BY r.user_id ) rc ON rc.userId = agg.userId LEFT JOIN interview_schedule ls ON ls.resume_id = agg.resumeId AND ls.interview_time = agg.maxTime LEFT JOIN interview_session se ON se.session_id = ls.session_id LEFT JOIN interview_slot sl ON sl.slot_id = ls.slot_id ORDER BY agg.maxTime IS NULL ASC, agg.maxTime ASC
